/**
 * A claim pays the desired amount, but never more than the policy's remaining
 * cap — successive claims against one policy draw down a shared budget.
 */
const claimResult = (
  step: ClaimStep,
  insuredItems: Item[],
  remainingCap: number,
): { payout: number; remainingCap: number } => {
  const desired = totalPayout(step.incident.damages, insuredItems);
  const payout = Math.min(desired, remainingCap);
  return { payout, remainingCap: remainingCap - payout };
};

